def order_total(prices, quantities, discounts):
    """Total cost of an order, rounded to 2 decimal places ONCE at the end.

    The three lists are parallel: line i sells quantities[i] units at
    prices[i] each, with discounts[i] (a 0..1 fraction) off that line.
    """
    total = 0.0
    for i in range(len(prices)):
        total += prices[i] * quantities[i] * (1 - discounts[i])
    return round(total, 2)


def receipt_lines(names, prices, quantities):
    """One 'name x qty @ price' string per line item, in order."""
    lines = []
    for i in range(len(names)):
        lines.append(f"{names[i]} x{quantities[i]} @ {prices[i]:.2f}")
    return lines

