from billing import order_total, receipt_lines


def test_total_rounds_once_at_the_end():
    # each line is 0.333; per-line rounding would give 0.33 * 3 = 0.99
    assert order_total([0.333, 0.333, 0.333], [1, 1, 1], [0, 0, 0]) == 1.0


def test_total_with_discounts():
    assert order_total([10.0, 4.0], [2, 3], [0.25, 0.0]) == 27.0


def test_total_empty_order():
    assert order_total([], [], []) == 0.0


def test_receipt_lines_format_and_order():
    got = receipt_lines(["apple", "pear"], [1.5, 0.25], [3, 12])
    assert got == ["apple x3 @ 1.50", "pear x12 @ 0.25"]


def test_receipt_lines_empty():
    assert receipt_lines([], [], []) == []

